style.css:
@-moz-document domain("pinterest.com") {
/* Cheri Liney everywhere */
    * {
        font-family: "Cheri Liney", cursive !important;
        color: #B0C4DE !important;
    }

    /* Icons */
    svg,
    svg *,
    path,
    circle,
    rect,
    polygon {
        fill: #B0C4DE !important;
        stroke: #B0C4DE !important;
    }

    /* Search bar */
    input,
    textarea {
        color: #B0C4DE !important;
        border-color: #B0C4DE !important;
    }

    /* Buttons */
    button,
    [role="button"] {
        color: #B0C4DE !important;
        border-color: #B0C4DE !important;
    }

    /* Links */
    a {
        color: #B0C4DE !important;
    }

    /* Pin titles */
    h1,
    h1 * {
        font-family: "Cheri Liney", cursive !important;
        color: #B0C4DE !important;
    }
}
